import{_ as e,c as s,o as t,ag as i}from"./chunks/framework.DuVOYUUM.js";const k=JSON.parse('{"title":"Installation Guide","description":"","frontmatter":{"order":2},"headers":[],"relativePath":"projects/igvc-2024/software/install-guide.md","filePath":"projects/igvc-2024/software/install-guide.md","lastUpdated":1790647345000}'),l={name:"projects/igvc-2024/software/install-guide.md"};function n(r,a,o,h,p,u){return t(),s("div",null,a[0]||(a[0]=[i(`<h1 id="installation-guide" tabindex="-1">Installation Guide <a class="header-anchor" href="#installation-guide" aria-label="Permalink to &quot;Installation Guide&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#ubuntu">Ubuntu</a><ul><li><a href="#native-install">Native Install</a></li><li><a href="#vm">VM</a></li><li><a href="#wsl2">WSL2</a></li></ul></li><li><a href="#ros-2">ROS 2</a></li><li><a href="#nav2">Nav2</a></li><li><a href="#zed-sdk">ZED SDK</a></li></ul></nav><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This guide goes over the steps to install some of the tools, software, and SDKs that we use.</p><h2 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to &quot;Ubuntu&quot;">​</a></h2><p>There are a few different methods to set up a Ubuntu system that works with ROS 2.</p><h3 id="native-install" tabindex="-1">Native Install <a class="header-anchor" href="#native-install" aria-label="Permalink to &quot;Native Install&quot;">​</a></h3><ol><li>Download the Ubuntu 22.04 ISO <a href="https://ubuntu.com/download/desktop" target="_blank" rel="noreferrer">here.</a></li><li>Make a bootable USB with the ISO. <ul><li><a href="https://rufus.ie/en/" target="_blank" rel="noreferrer">Rufus</a></li><li><a href="https://etcher.balena.io/" target="_blank" rel="noreferrer">Balena Etcher</a></li></ul></li><li><a href="https://ubuntu.com/tutorials/install-ubuntu-desktop#1-overview" target="_blank" rel="noreferrer">Install Ubuntu Desktop</a></li><li><a href="#ros-2">Install ROS 2</a></li></ol><h3 id="vm" tabindex="-1">VM <a class="header-anchor" href="#vm" aria-label="Permalink to &quot;VM&quot;">​</a></h3><ol><li>Download the Ubuntu 22.04 ISO <a href="https://ubuntu.com/download/desktop" target="_blank" rel="noreferrer">here.</a></li><li>Install a VM hypervisor: <ul><li><a href="https://www.virtualbox.org/" target="_blank" rel="noreferrer">VirtualBox</a></li><li><a href="https://www.vmware.com/products/workstation-player.html" target="_blank" rel="noreferrer">VMware Workstation Player</a></li></ul></li><li><a href="https://ubuntu.com/tutorials/install-ubuntu-desktop#1-overview" target="_blank" rel="noreferrer">Install Ubuntu Desktop</a></li><li><a href="#ros-2">Install ROS 2</a></li></ol><h3 id="wsl2" tabindex="-1">WSL2 <a class="header-anchor" href="#wsl2" aria-label="Permalink to &quot;WSL2&quot;">​</a></h3><ol><li>Open PowerShell or Windows Command Prompt in administrator mode by right-clicking and selecting &quot;Run as administrator&quot;</li><li>Then enter the instllation command: <code>wsl --install --d Ubuntu-22.04</code></li><li>Then restart your machine.</li><li><a href="#ros-2">Install ROS 2</a></li></ol><h2 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h2><ol><li><a href="https://docs.ros.org/en/humble/Installation/Ubuntu-Install-Debians.html" target="_blank" rel="noreferrer">Install ROS 2 Humble</a><ul><li>Be sure to do the full desktop install (<code>sudo apt install ros-humble-desktop</code>).</li><li>To verify that your installation works correctly, try the examples.</li></ul></li><li>Run these commands:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;source /opt/ros/humble/setup.bash&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .bashrc</span></span></code></pre></div><p>This will make it so the <code>source</code> command will be run for you automatically every time you open a new terminal.</p><h2 id="nav2" tabindex="-1">Nav2 <a class="header-anchor" href="#nav2" aria-label="Permalink to &quot;Nav2&quot;">​</a></h2><p>Install Nav2 with these commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ros-humble-navigation2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ros-humble-nav2-bringup </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ros-humble-turtlebot3-gazebo </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span></code></pre></div><p>Verify the installation was successful by running these commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TURTLEBOT3_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">waffle</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GAZEBO_MODEL_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$GAZEBO_MODEL_PATH:/opt/ros/humble/share/turtlebot3_gazebo/models</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nav2_bringup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tb3_simulation_launch.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless:=False</span></span></code></pre></div><p>For more information, see the <a href="https://navigation.ros.org/getting_started/index.html" target="_blank" rel="noreferrer">Nav2 documentation</a>.</p><h2 id="zed-sdk" tabindex="-1">ZED SDK <a class="header-anchor" href="#zed-sdk" aria-label="Permalink to &quot;ZED SDK&quot;">​</a></h2><p>The ZED SDK can be installed on both Ubuntu and Windows. If you are installing on Windows, make sure you have CUDA installed beforehand.</p><ol><li>Install the ZED SDK <ul><li><a href="https://www.stereolabs.com/docs/installation/windows" target="_blank" rel="noreferrer">Windows</a></li><li><a href="https://www.stereolabs.com/docs/installation/linux" target="_blank" rel="noreferrer">Ubuntu</a></li><li>Accept all the default options for the installation</li></ul></li><li>Verify that the installation was successful by running the ZED Explorer and ZED Depth Viewer.</li><li>If you installed it on Ubuntu, you can also play with the <a href="https://www.stereolabs.com/docs/ros2" target="_blank" rel="noreferrer">ROS 2 tools</a>.</li></ol>`,25)]))}const c=e(l,[["render",n]]);export{k as __pageData,c as default};
